#pragma once
#include "graphics.hpp"
struct NativeFontWidths{int8_t left=0;uint8_t width=0;int8_t advance=0;};
struct NativeFontMap{uint16_t begin=0,end=0;std::map<uint16_t,uint16_t> values;};
struct NativeResourceFont{
    uint8_t cellWidth=0,cellHeight=0,height=0,width=0,ascent=0;int8_t baseline=0,linefeed=0;uint16_t columns=0,rows=0,alternate=0;NativeFontWidths defaultWidths;std::map<uint16_t,NativeFontWidths> widths;std::vector<NativeFontMap> maps;std::vector<TextureImage> sheets;
    uint16_t glyphIndex(uint16_t code)const{for(const auto& map:maps)if(code>=map.begin&&code<=map.end){auto found=map.values.find(code);return found==map.values.end()||found->second==0xFFFF?alternate:found->second;}return alternate;}
    NativeFontWidths glyphWidths(uint16_t index)const{auto found=widths.find(index);return found==widths.end()?defaultWidths:found->second;}
    std::array<uint32_t,3> glyphCell(uint16_t index)const{uint32_t count=uint32_t(columns)*rows;assetCheck(count&&index/count<sheets.size(),"Font glyph outside sheets");return {index/count,(index%count%columns)*(cellWidth+1u)+1,(index%count/columns)*(cellHeight+1u)+1};}
};
inline NativeResourceFont decodeResourceFont(BinaryView data){
    assetCheck(data.size()>=16&&data.tag(0)=="RFNT"&&data.u16(4)==0xFEFF&&(data.u16(6)==0x102||data.u16(6)==0x104)&&data.u32(8)==data.size(),"Invalid resource font header");size_t cursor=data.u16(12);assetCheck(cursor>=16,"Invalid resource font header size");std::map<uint32_t,std::pair<std::string,BinaryView>> blocks;uint32_t info=0;
    for(unsigned i=0;i<data.u16(14);++i){extent(cursor,8,data.size());auto length=data.u32(cursor+4);assetCheck(length>=8,"Invalid resource font block size");auto body=data.sub(cursor+8,length-8);auto tag=data.tag(cursor);assetCheck(tag=="FINF"||tag=="TGLP"||tag=="CWDH"||tag=="CMAP","Unsupported resource font block");blocks.emplace(uint32_t(cursor+8),std::make_pair(tag,body));if(tag=="FINF"){assetCheck(!info,"Duplicate resource font info");info=uint32_t(cursor+8);}cursor+=length;}
    assetCheck(cursor==data.size()&&info,"Incomplete resource font blocks");auto get=[&](uint32_t pointer,const char* kind){auto found=blocks.find(pointer);assetCheck(found!=blocks.end()&&found->second.first==kind,"Invalid resource font block pointer");return found->second.second;};auto finf=get(info,"FINF");extent(0,24,finf.size());assetCheck(finf.u8(0)==1&&finf.u8(7)==1,"Unsupported resource font type/encoding");NativeResourceFont font;font.linefeed=int8_t(finf.u8(1));font.alternate=finf.u16(2);font.defaultWidths={int8_t(finf.u8(4)),finf.u8(5),int8_t(finf.u8(6))};font.height=finf.u8(20);font.width=finf.u8(21);font.ascent=finf.u8(22);assetCheck(font.width&&font.height,"Invalid resource font dimensions");auto glyphPointer=finf.u32(8);auto glyph=get(glyphPointer,"TGLP");extent(0,24,glyph.size());font.cellWidth=glyph.u8(0);font.cellHeight=glyph.u8(1);font.baseline=int8_t(glyph.u8(2));font.columns=glyph.u16(12);font.rows=glyph.u16(14);auto count=glyph.u16(8),format=glyph.u16(10),w=glyph.u16(16),h=glyph.u16(18);auto sheetSize=glyph.u32(4),image=glyph.u32(20);assetCheck(count&&count<=1024&&font.columns&&font.rows&&font.cellWidth&&font.cellHeight,"Invalid resource font sheet grid");assetCheck(uint32_t(font.columns)*(font.cellWidth+1)<=w&&uint32_t(font.rows)*(font.cellHeight+1)<=h&&sheetSize==gxEncodedSize(w,h,format),"Invalid resource font sheet dimensions/size");assetCheck(image>=uint64_t(glyphPointer)+24,"Font sheet image overlaps glyph metadata");extent(image,uint64_t(count)*sheetSize,uint64_t(glyphPointer)+glyph.size());assetCheck(uint64_t(count)*font.columns*font.rows<=65536,"Excess resource font glyph capacity");for(unsigned i=0;i<count;++i){auto sheet=decodeGxTexture(data,w,h,format,image+uint64_t(i)*sheetSize,data.sub(0,0));sheet.wrapS=sheet.wrapT=0;font.sheets.push_back(std::move(sheet));}uint32_t capacity=uint32_t(count)*font.columns*font.rows;assetCheck(font.alternate<capacity,"Invalid font alternate glyph");
    std::set<uint32_t> visited;for(uint32_t pointer=finf.u32(12);pointer;){assetCheck(visited.insert(pointer).second,"Cyclic font width chain");auto width=get(pointer,"CWDH");extent(0,8,width.size());auto begin=width.u16(0),end=width.u16(2);assetCheck(begin<=end&&end<capacity,"Invalid font width range");extent(8,uint64_t(end-begin+1)*3,width.size());for(unsigned i=begin;i<=end;++i){size_t p=8+(i-begin)*3;assetCheck(width.u8(p+1)<=font.cellWidth,"Font glyph wider than cell");font.widths.emplace(uint16_t(i),NativeFontWidths{int8_t(width.u8(p)),width.u8(p+1),int8_t(width.u8(p+2))});}pointer=width.u32(4);}
    visited.clear();for(uint32_t pointer=finf.u32(16);pointer;){assetCheck(visited.insert(pointer).second,"Cyclic font map chain");auto map=get(pointer,"CMAP");extent(0,12,map.size());NativeFontMap decoded;decoded.begin=map.u16(0);decoded.end=map.u16(2);assetCheck(decoded.begin<=decoded.end,"Invalid font code range");auto method=map.u16(4);auto put=[&](uint16_t code,uint32_t index){assetCheck(index==0xFFFF||index<capacity,"Font map index outside sheets");assetCheck(decoded.values.emplace(code,uint16_t(index)).second,"Duplicate font scan code");};if(method==0){auto first=map.u16(12);for(unsigned code=decoded.begin;code<=decoded.end;++code)put(uint16_t(code),first+code-decoded.begin);}else if(method==1){extent(12,uint64_t(decoded.end-decoded.begin+1)*2,map.size());for(unsigned code=decoded.begin;code<=decoded.end;++code)put(uint16_t(code),map.u16(12+(code-decoded.begin)*2));}else if(method==2){auto entries=map.u16(12);extent(14,uint64_t(entries)*4,map.size());uint16_t prior=0;for(unsigned i=0;i<entries;++i){auto code=map.u16(14+i*4);assetCheck(code>=decoded.begin&&code<=decoded.end&&(!i||code>prior),"Invalid font scan order/range");put(code,map.u16(16+i*4));prior=code;}}else throw std::runtime_error("Unsupported font map method");font.maps.push_back(std::move(decoded));pointer=map.u32(8);}return font;
}
inline void resourceFontLookupTests(){NativeResourceFont font;font.alternate=7;NativeFontMap first;first.begin=32;first.end=34;first.values={{32,0},{33,0xFFFF},{34,2}};NativeFontMap second;second.begin=0;second.end=0xFFFF;second.values={{33,5},{65,6}};font.maps={first,second};assetCheck(font.glyphIndex(33)==7&&font.glyphIndex(65)==6&&font.glyphIndex(100)==7,"Font map precedence/fallback mismatch");font.columns=2;font.rows=2;font.cellWidth=3;font.cellHeight=5;font.sheets.resize(2);assetCheck(font.glyphCell(5)==std::array<uint32_t,3>{1,5,1},"Font sheet/cell border mapping mismatch");}



